-- Test-only minimum persistence contract. Production schema/roles remain the admitted host's responsibility.
CREATE TABLE app_models(tenant text NOT NULL,app text NOT NULL,entity text NOT NULL,version text NOT NULL,definition jsonb NOT NULL,PRIMARY KEY(tenant,app,entity));
CREATE TABLE app_records(tenant text NOT NULL,app text NOT NULL,entity text NOT NULL,id text NOT NULL,revision bigint NOT NULL CHECK(revision>0),version text NOT NULL,fields jsonb NOT NULL,PRIMARY KEY(tenant,app,entity,id),FOREIGN KEY(tenant,app,entity) REFERENCES app_models(tenant,app,entity));
CREATE TABLE app_jobs(tenant text NOT NULL,app text NOT NULL,id text NOT NULL,action text NOT NULL,actor text NOT NULL,permission text NOT NULL,package_digest text NOT NULL,request_key text NOT NULL,input_digest text NOT NULL,input jsonb NOT NULL,status text NOT NULL DEFAULT 'queued',progress integer NOT NULL DEFAULT 0,lease text,lease_until timestamptz,started_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),revision bigint NOT NULL DEFAULT 1,message jsonb NOT NULL DEFAULT '{}',result jsonb,PRIMARY KEY(tenant,app,id),UNIQUE(tenant,app,request_key));
CREATE TABLE outbox(id bigserial PRIMARY KEY,tenant text NOT NULL,kind text NOT NULL CHECK(kind<>'reject-fixture' AND NOT(tenant='secret-reject' AND kind='app.secret_rotated')),data jsonb NOT NULL);
CREATE TABLE app_packages(tenant text NOT NULL,id text NOT NULL,version text NOT NULL DEFAULT '1.0.0',manifest jsonb NOT NULL,digest text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,revision bigint NOT NULL DEFAULT 1,PRIMARY KEY(tenant,id));
CREATE TABLE app_versions(tenant text NOT NULL,app text NOT NULL,version text NOT NULL,digest text NOT NULL,manifest jsonb NOT NULL,PRIMARY KEY(tenant,app,version));
CREATE TABLE app_record_indexes(tenant text NOT NULL,app text NOT NULL,entity text NOT NULL,record_id text NOT NULL,field text NOT NULL,value_hash bytea NOT NULL,value jsonb NOT NULL);

CREATE TABLE app_service_secrets(tenant text NOT NULL,app text NOT NULL,kind text NOT NULL,ciphertext text NOT NULL,package_digest text NOT NULL,revision bigint NOT NULL,actor text NOT NULL,rotated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant,app,kind),FOREIGN KEY(tenant,app) REFERENCES app_packages(tenant,id));

CREATE TABLE developer_builds(id text PRIMARY KEY,tenant text NOT NULL,environment text NOT NULL,app text NOT NULL,version text NOT NULL,digest text NOT NULL,manifest jsonb NOT NULL,prompt text NOT NULL,provider text NOT NULL,model text,summary jsonb NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state<>'staged' OR id<>'version-state-fail'),created_at timestamptz NOT NULL DEFAULT now(),archived boolean NOT NULL DEFAULT false,archived_at timestamptz,UNIQUE(tenant,app,version));

CREATE TABLE shop_environments(tenant text NOT NULL,live_tenant text NOT NULL,PRIMARY KEY(tenant,live_tenant));
CREATE TABLE developer_drafts(tenant text NOT NULL,actor_key text NOT NULL,id text NOT NULL,manifest jsonb NOT NULL,environment text,revision bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant,actor_key,id),FOREIGN KEY(environment,tenant) REFERENCES shop_environments(tenant,live_tenant));
